import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"关于 _replace.csv","description":"","frontmatter":{},"headers":[],"relativePath":"translation/Replace_CSV.md","filePath":"translation/Replace_CSV.md"}`),a={name:`translation/Replace_CSV.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="关于-replace-csv" tabindex="-1">关于 <code>_replace.csv</code> <a class="header-anchor" href="#关于-replace-csv" aria-label="Permalink to “关于 _replace.csv”">​</a></h1><blockquote><p>翻译自原文档：<a href="https://osdn.net/projects/emuera/wiki/replace" target="_blank" rel="noreferrer">https://osdn.net/projects/emuera/wiki/replace</a></p></blockquote><p>在 <code>CSV/</code> 文件夹中放置一个名为 <code>_replace.csv</code> 的文件，就可以对显示相关的项目进行设置。</p><h2 id="金钱单位" tabindex="-1">金钱单位 <a class="header-anchor" href="#金钱单位" aria-label="Permalink to “金钱单位”">​</a></h2><p><code>お金の単位</code> 用于设置附加在 <code>PRINT_SHOPITEM</code> 所显示的商品价格上的单位。</p><p>默认值是 <code>$</code>。也可以使用包含全角字符或多个字符的字符串。</p><h2 id="单位位置" tabindex="-1">单位位置 <a class="header-anchor" href="#单位位置" aria-label="Permalink to “单位位置”">​</a></h2><p><code>単位の位置</code> 用于设置 <code>PRINT_SHOPITEM</code> 所显示的商品价格中，单位位于数字之前还是之后。</p><p>有效值为<code>前</code>或<code>後</code>，默认值为<code>後</code>。</p><h2 id="启动时的简略显示" tabindex="-1">启动时的简略显示 <a class="header-anchor" href="#启动时的简略显示" aria-label="Permalink to “启动时的简略显示”">​</a></h2><p><code>起動時簡略表示</code> 用于设置当配置中关闭了<code>加载时显示报告</code>功能时，取而代之显示的字符串。</p><p>默认值是 <code>Now Loading...</code>。</p><h2 id="出售的物品数量" tabindex="-1">出售的物品数量 <a class="header-anchor" href="#出售的物品数量" aria-label="Permalink to “出售的物品数量”">​</a></h2><p><code>販売アイテム数</code> 用于设置购买处理中，哪些数值表示商品（进而调用 <code>@EVENTBUY</code>），哪些数值表示用户选项（进而调用 <code>@USERSHOP</code>）。</p><p>在 Eramaker 通常的 <code>SHOP</code> 处理中，<code>PRINT_SHOPITEM</code> 会显示所有 <code>ITEMSALES</code> 非 0 的 <code>ITEMNAME</code>（0～999）。</p><p>另一方面，只有输入 0～99 时才会进行购买处理和 <code>@EVENTBUY</code>；输入其他数值时会调用 <code>@USERSHOP</code>。</p><p>Emuera 基本上重现了这一处理。</p><p>改变<code>販売アイテム数</code>会改变进行购买处理的物品范围。</p><p>例如，把<code>販売アイテム数</code>设为 <code>1000</code> 时，输入 0～999 会进行购买处理，输入负值或大于等于 1000 的值则会调用 <code>@USERSHOP</code>。</p><blockquote><p>注意：输入 0～（<code>販売アイテム数</code>-1）之间的值时，无论购买是否成功，都不会调用 <code>@USERSHOP</code>。</p></blockquote><p>例如，<code>販売アイテム数</code>为 <code>1000</code> 时，<code>[200] - 保存</code>或<code>[300] - 读取</code>会被视为试图购买第 200、300 号物品，因而不会调用 <code>@USERSHOP</code>。</p><p>如果你想增加（或减少）<code>PRINT_SHOPITEM</code> 中显示的物品数量，请修改 <code>VariableSize.csv</code> 中 <code>ITEMNAME</code> 和 <code>ITEMSALES</code> 数组的元素数量。</p><p><code>ITEMNAME</code> 和 <code>ITEMSALES</code> 数组中元素数量较小的一方，就是 <code>PRINT_SHOPITEM</code> 显示的物品范围。</p><h2 id="drawline-字符" tabindex="-1">DRAWLINE 字符 <a class="header-anchor" href="#drawline-字符" aria-label="Permalink to “DRAWLINE 字符”">​</a></h2><p><code>DRAWLINE文字</code> 用于设置 <code>DRAWLINE</code> 指令绘制分隔线时使用的字符。</p><p>默认字符是 <code>-</code>。</p><h2 id="bar-字符" tabindex="-1">BAR 字符 <a class="header-anchor" href="#bar-字符" aria-label="Permalink to “BAR 字符”">​</a></h2><p><code>BAR文字1</code> 与 <code>BAR文字2</code> 用于设置 <code>BAR</code> 或 <code>BARL</code> 指令中使用的字符。</p><p>默认情况下 <code>BAR文字1</code> 是 <code>*</code>，<code>BAR文字2</code> 是 <code>.</code>。</p><p>此时会显示为 <code>[****....]</code> 这样的形式。</p><p>也可以指定全角字符或由多个字符组成的字符串，但需要考虑显示会错位的问题。</p><p>另外，如果指定数字，Emuera 会把 <code>[88881111]</code> 之类的文本视为可点击的按钮，从而产生不自然的动作。</p><h2 id="系统菜单" tabindex="-1">系统菜单 <a class="header-anchor" href="#系统菜单" aria-label="Permalink to “系统菜单”">​</a></h2><p><code>システムメニュー0</code>、<code>システムメニュー1</code> 用于设置标题画面最初显示的两个选项的文字。</p><p>默认值分别是 <code>最初からはじめる</code>（从头开始）、<code>ロードしてはじめる</code>（读取存档），显示效果如下：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>[0] 最初からはじめる</span></span>
<span class="line"><span>[1] ロードしてはじめる</span></span></code></pre></div><p>如果定义 <code>@SYSTEM_TITLE</code> 来使用自定义标题画面，则这里指定的字符串不会被使用。</p><p>请在 <code>@SYSTEM_TITLE</code> 中实现显示处理。</p><h2 id="com-able-的初始值" tabindex="-1">COM_ABLE 的初始值 <a class="header-anchor" href="#com-able-的初始值" aria-label="Permalink to “COM_ABLE 的初始值”">​</a></h2><p><code>COM_ABLE初期値</code> 用于设置在 <code>TRAIN</code> 中找不到 <code>@COM_ABLE{X}</code> 时所采用的值。</p><p>默认值是 1，即没有定义对应的 <code>@COM_ABLE</code> 时，认为该 <code>COM</code> 可以执行。</p><p>如果把这个值设为 0，则没有定义 <code>@COM_ABLE</code> 时会认为该 <code>COM</code> 不可执行。</p><blockquote><p><code>@COM_ABLE{X}</code> 函数用于判断某个调教指令在当前状态下对当前目标是否可用。 返回 <code>1</code> 表示该指令可用并显示在指令菜单中；返回 <code>0</code> 表示不可用，不会显示该指令。</p></blockquote><h2 id="污渍的初始值" tabindex="-1">污渍的初始值 <a class="header-anchor" href="#污渍的初始值" aria-label="Permalink to “污渍的初始值”">​</a></h2><p><code>汚れの初期値</code> 用于设置 <code>STAIN</code> 被初始化时赋予的值。</p><p>用 <code>/</code> 分隔即可指定 <code>STAIN:1</code> 之后的值。</p><p>默认值是 <code>0, 0, 2, 1, 8</code>。</p><h2 id="超时显示" tabindex="-1">超时显示 <a class="header-anchor" href="#超时显示" aria-label="Permalink to “超时显示”">​</a></h2><p><code>時間切れ表示</code> 用于设置像 <code>TINPUT</code> 这样有时间限制的输入指令在超时时显示的字符串。</p><p>默认值是 <code>時間切れ</code>（已超时）。</p><h2 id="explv-的初始值" tabindex="-1">EXPLV 的初始值 <a class="header-anchor" href="#explv-的初始值" aria-label="Permalink to “EXPLV 的初始值”">​</a></h2><p><code>EXPLVの初期値</code> 用于设置 <code>EXPLV</code> 的初始值，即调教经验（<code>EXP</code>）每提升一个等级所需的数值。</p><p>用 <code>/</code> 分隔即可指定 <code>EXPLV:1</code> 之后的值。</p><p>默认值是 <code>0, 1, 4, 20, 50, 200</code>。</p><h2 id="palamlv-的初始值" tabindex="-1">PALAMLV 的初始值 <a class="header-anchor" href="#palamlv-的初始值" aria-label="Permalink to “PALAMLV 的初始值”">​</a></h2><p><code>PALAMLVの初期値</code> 用于设置 <code>PALAMLV</code> 的初始值，即调教参数（<code>PALAM</code>）每提升一个等级所需的数值。</p><p>用 <code>/</code> 分隔即可指定 <code>PALAMLV:1</code> 之后的值。</p><p>默认值是 <code>0, 100, 500, 3000, 10000, 30000, 60000, 100000, 150000, 250000</code>。</p><h2 id="pband-的初始值" tabindex="-1">PBAND 的初始值 <a class="header-anchor" href="#pband-的初始值" aria-label="Permalink to “PBAND 的初始值”">​</a></h2><p><code>PBANDの初期値</code> 用于设置 <code>PBAND:0</code> 的初始值。</p><p>默认值是 <code>4</code>。</p><h2 id="relation-的初始值" tabindex="-1">RELATION 的初始值 <a class="header-anchor" href="#relation-的初始值" aria-label="Permalink to “RELATION 的初始值”">​</a></h2><p><code>RELATIONの初期値</code> 用于设置 <code>CharaXX.csv</code> 中未指定 <code>RELATION</code> 时该值的初始值。</p><p>默认值是 <code>0</code>。</p>`,64)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};